"""Subject object files: obj_vehicle, obj_food, obj_drink, obj_animal, obj_plant, obj_instrument, obj_tool, obj_sport, obj_kitchen, obj_tech, obj_toy2, obj_stationery, obj_sign. Each: obj_<s> (full descriptions), obj_<s>_item, obj_<s>_look, obj_<s>_prompt."""
import os, re, sys, random, zlib
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE)
from paths import FINAL
def S(x): return [i.strip() for i in x.split(';') if i.strip()]
def R(*k): return random.Random(zlib.crc32('|'.join(map(str, k)).encode()))
