D['sign'] = (S("a hand-painted shop sign; a neon open sign; a wooden road sign; a vintage tin advertisement; a cinema marquee; a chalkboard menu; a street-name sign; a billboard; a banner on a pole; a stone engraved sign; a lantern with a name; a window decal; a pub hanging sign; a barber pole; a pharmacy cross sign; a graffiti tag; a mural lettering; a bus-stop sign; a no-entry sign; a warning triangle; an exit sign; a menu board; a flag on a mast; a pennant string; a wayfinding totem; a protest placard; a banner at a festival; a fabric shop flag; a ship's nameplate"), 'sign')
def mk():
    G = {}
    for k, (items, _) in D.items():
        G[f'obj_{k}_item'] = items; G[f'obj_{k}_look'] = COND
        G[f'obj_{k}'] = sorted({f"{it}, {R(k, it, c).choice(COL)}, {c}" for it in items for c in COND if R('s', k, it, c).random() < .25})
        G[f'obj_{k}_prompt'] = [f"__obj_{k}__.", f"A still life featuring __obj_{k}_item__, __obj_{k}_look__."]
    G['obj_subject_prompt'] = [f"__obj_{k}__." for k in D]
    return G
def build(): return mk()
def run(final):
    G = build()
    for n, l in G.items():
        assert l and all(l), n
        open(os.path.join(final, n + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(dict.fromkeys(l)) + '\n')
    print('objects:', len(G), 'files'); return G
def export_aoo(out, prefix='aoo_'):
    G = build(); names_ = set(G); ref = re.compile(r'__([A-Za-z0-9_\-/]+)__'); n = 0
    for name, lines in G.items():
        keep = list(dict.fromkeys(ref.sub(lambda m: '__' + prefix + m.group(1) + '__' if m.group(1) in names_ else m.group(0), l) for l in lines))
        if not name.endswith('prompt'): random.Random(zlib.crc32(name.encode())).shuffle(keep)
        open(os.path.join(out, prefix + name + '.txt'), 'w', encoding='utf8', newline='\n').write('\n'.join(keep) + '\n'); n += 1
    return n
if __name__ == '__main__':
    a = [x for x in sys.argv[1:] if os.path.isdir(x)]; run(os.path.abspath(a[0]) if a else FINAL)
